    var playoffCount = num($('playoffCount'));
    var playoffCategories = num($('playoffCategories'));
    var minutesPerGame = num($('minutesPerGame'));
    var pause = num($('pauseBetweenGames'));

    var groupGames = teams * gamesPerTeam / 2;
