    var totalHours = totalGames * interval / 60;

    $('groupcount').textContent = '~' + Math.round(teams / (gamesPerTeam + 1));
    $('totalGames').textContent = Math.round(totalGames);
    $('totalGames_group').textContent = Math.round(groupGames);
    $('totalGames_playoffs').textContent = Math.round(playoffGames);
    $('minutesBetweenGameStarts').textContent = interval;
    $('gamesPerHour').textContent = gamesPerHour;
    $('totalHours').textContent = '~' + Math.ceil(totalHours);
    $('totalHours2').textContent = '~' + Math.ceil(totalHours);

    var parts = ($('startTime').value || '08:00').split(':');
    var parts2 = ($('endTime').value || '20:00').split(':');
    var hoursPerDay = (parseInt(parts2[0],10)*60 + parseInt(parts2[1],10) - parseInt(parts[0],10)*60 - parseInt(parts[1],10)) / 60;
    var days = num($('days'));
    var fields = totalHours / (hoursPerDay * days);
    $('totalFieldsRounded').textContent = Math.ceil(fields);
    $('totalFields').textContent = '(' + (Math.round(fields * 100) / 100) + ')';

